void VkEncoder::vkFreeCommandBuffers(VkDevice device, VkCommandPool commandPool,
                                     uint32_t commandBufferCount,
                                     const VkCommandBuffer* pCommandBuffers, uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    size_t count = 0;
    count += 2 * 8;
    count += sizeof(uint32_t);
    count += 8;
    if (pCommandBuffers) {
        if (commandBufferCount) {
            count += commandBufferCount * 8;
        }
    }
    uint8_t* streamPtr =
        reservePacket(stream, OP_vkFreeCommandBuffers, count, queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_device_to_host_u64(device));
    writeStreamVal(&streamPtr, gfxstream_vk_command_pool_to_host_u64(commandPool));
    writeStreamBytes(&streamPtr, &commandBufferCount, sizeof(uint32_t));
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pCommandBuffers);
    if (pCommandBuffers) {
        if (commandBufferCount) {
            for (uint32_t k = 0; k < commandBufferCount; ++k) {
                writeStreamVal(&streamPtr,
                               gfxstream_vk_command_buffer_to_host_u64(pCommandBuffers[k]));
            }
        }
    }
    stream->flush();
    if (pCommandBuffers) {
        for (uint32_t i = 0; i < commandBufferCount; ++i) {
            sResourceTracker->unregister_VkCommandBuffer(pCommandBuffers[i]);
            delete_gfxstream_vk_command_buffer(
                device, pCommandBuffers[i],
                &gfxstream_vk_command_pool_from_handle(commandPool)->base.alloc);
        }
    }
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

