void VkEncoder::vkGetDeviceImageSparseMemoryRequirements(
    VkDevice device, const VkDeviceImageMemoryRequirements* pInfo,
    uint32_t* pSparseMemoryRequirementCount,
    VkSparseImageMemoryRequirements2* pSparseMemoryRequirements, uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    auto pool = mImpl->pool();
    VkDeviceImageMemoryRequirements* local_pInfo = nullptr;
    if (pInfo) {
        local_pInfo = (VkDeviceImageMemoryRequirements*)pool->alloc(
            sizeof(const VkDeviceImageMemoryRequirements));
        deepcopy_VkDeviceImageMemoryRequirements(pool, VK_STRUCTURE_TYPE_MAX_ENUM, pInfo,
                                                 (VkDeviceImageMemoryRequirements*)(local_pInfo));
    }
    if (local_pInfo) {
        transform_tohost_VkDeviceImageMemoryRequirements(
            sResourceTracker, (VkDeviceImageMemoryRequirements*)(local_pInfo));
    }
    size_t count = 0;
    count += 8;
    count_VkDeviceImageMemoryRequirements(sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                                          (VkDeviceImageMemoryRequirements*)(local_pInfo), &count);
    count += 8;
    if (pSparseMemoryRequirementCount) {
        count += sizeof(uint32_t);
    }
    count += 8;
    if (pSparseMemoryRequirements) {
        if (pSparseMemoryRequirementCount) {
            for (uint32_t i = 0; i < (uint32_t)(*pSparseMemoryRequirementCount); ++i) {
                count_VkSparseImageMemoryRequirements2(
                    sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                    (VkSparseImageMemoryRequirements2*)(pSparseMemoryRequirements + i), &count);
            }
        }
    }
    uint8_t* streamPtr = reservePacket(stream, OP_vkGetDeviceImageSparseMemoryRequirements, count,
                                       queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_device_to_host_u64(device));
    reservedmarshal_VkDeviceImageMemoryRequirements(stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                                                    (VkDeviceImageMemoryRequirements*)(local_pInfo),
                                                    &streamPtr);
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pSparseMemoryRequirementCount);
    if (pSparseMemoryRequirementCount) {
        writeStreamBytes(&streamPtr, pSparseMemoryRequirementCount, sizeof(uint32_t));
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pSparseMemoryRequirements);
    if (pSparseMemoryRequirements) {
        for (uint32_t i = 0; i < (uint32_t)(*pSparseMemoryRequirementCount); ++i) {
            reservedmarshal_VkSparseImageMemoryRequirements2(
                stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                (VkSparseImageMemoryRequirements2*)(pSparseMemoryRequirements + i), &streamPtr);
        }
    }
    uint64_t check_pSparseMemoryRequirementCount = stream->getBe64();
    if (pSparseMemoryRequirementCount) {
        if (!(check_pSparseMemoryRequirementCount)) {
            GFXSTREAM_ERROR(
                "fatal: pSparseMemoryRequirementCount inconsistent between guest and host");
        }
        stream->read(pSparseMemoryRequirementCount, sizeof(uint32_t));
    }
    uint64_t check_pSparseMemoryRequirements = stream->getBe64();
    if (pSparseMemoryRequirements) {
        if (!(check_pSparseMemoryRequirements)) {
            GFXSTREAM_ERROR("fatal: pSparseMemoryRequirements inconsistent between guest and host");
        }
        if (pSparseMemoryRequirementCount) {
            for (uint32_t i = 0; i < (uint32_t)(*pSparseMemoryRequirementCount); ++i) {
                unmarshal_VkSparseImageMemoryRequirements2(
                    stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                    (VkSparseImageMemoryRequirements2*)(pSparseMemoryRequirements + i));
            }
        }
    }
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

